-- Extend the server-only reader with an exact frozen full-data JSON whitelist.
-- This adds no table, schema, browser, public, authenticated, legacy, World,
-- OpeningSeed, worker, or mutation capability. CSV and source provenance files
-- remain outside this structured-query policy.

do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'world_v2_api_reader')
     or not exists (select 1 from pg_roles where rolname = 'world_v2_api_login') then
    raise exception 'World V2 full-data reader requires the reviewed country-reader roles';
  end if;
  if exists (
    select 1 from pg_policies
    where schemaname = 'world_v2'
      and tablename = 'country_candidate_artifact'
      and policyname = 'country_candidate_artifact_selected_full_source_server_read'
  ) then
    raise exception 'World V2 full-data reader policy must be absent before reviewed publication';
  end if;
end;
$$;

create policy country_candidate_artifact_selected_full_source_server_read
on world_v2.country_candidate_artifact
for select
to world_v2_api_reader
using (
  bundle_id = 'BALANCED_2026_09_28_V1'
